 83	                severity: 'warning',
 84	                message: `Repository "${repoId}" is not cloned.`,
 85	                fixAction: 'setup-workspace',
 86	                repositoryId: repoId,
 87	            });
 88	        }
 89	    }
 90	
 91	    // Check 3: (Optional) Credential-missing errors from the most recent setup run.
 92	    // Query all credential entries (both 'error' and 'info') for this workspace
