102	        // Filter to entries scoped to this workspace.
103	        const wsEntries = entries.filter(
104	            (e) =>
105	                e.Context.WorkspaceId === workspaceId &&
106	                e.Context.ProjectId === projectId &&
107	                e.Context.RepositoryId !== undefined,
108	        );
109	
110	        // De-duplicate by repository ID, keeping only the most recent entry per repo
111	        // (entries are returned newest-first from errorLogManager.list()).
112	        // Only push a credential-missing issue when the most recent entry is an error.
113	        const seenRepos = new Set<string>();
114	        for (const entry of wsEntries) {
115	            const repoId = entry.Context.RepositoryId!;
116	            if (!seenRepos.has(repoId)) {
117	                seenRepos.add(repoId);
118	                if (entry.Severity === 'error') {
119	                    issues.push({
120	                        type: 'credential-missing',
121	                        severity: 'warning',
122	                        message: entry.Message,
123	                        fixAction: 'configure-credential',
124	                        repositoryId: repoId,
125	                    });
126	                }
127	                // Severity: 'info' means the most recent credential operation
128	                // succeeded — suppress any stale credential-missing badge.
129	            }
130	        }
131	    }
132	
133	    return {
134	        healthy: issues.length === 0,
135	        issues,
136	    };
